const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".rm{box-sizing:border-box;width:100%;height:100%;min-width:0;min-height:0;display:flex;flex-direction:column;gap:6px;padding:10px;color:var(--ink);font:12px/1.4 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;overflow:hidden}\n.rm *{box-sizing:border-box}\n.rm.sz-3x3{padding:8px;gap:5px}\n.rm button{font:inherit;cursor:pointer}\n.pane{display:flex;flex-direction:column;gap:6px;min-width:0;min-height:0;flex:1}\n.split{display:grid;grid-template-columns:164px minmax(0,1fr);gap:8px;flex:1;min-height:0;min-width:0}\n.rt{background:var(--panel-paper);border:1px solid var(--line);border-radius:12px;padding:8px;overflow:hidden}\n.hd{display:flex;align-items:center;justify-content:space-between;gap:6px;flex:none}\n.ttl{font-weight:700;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}\n.cnt{margin-left:5px;color:var(--muted);font-weight:500;font-size:11px}\n\n.btn{flex:none;height:24px;padding:0 9px;border:1px solid var(--line);border-radius:8px;background:var(--button-paper,var(--panel-paper));color:var(--ink);white-space:nowrap;line-height:1}\n.btn.pri{background:var(--accent);color:var(--on-accent);border-color:var(--accent);font-weight:600}\n.btn.sm{height:22px;padding:0 8px;font-size:11px}\n.btn.ico{width:26px;padding:0;font-size:14px}\n.btn.warn{color:#B4533A;border-color:#B4533A;font-weight:700}\n.btn:disabled{opacity:.5;cursor:default}\n.btn:focus-visible,.inp:focus-visible,.row:focus-visible,.chip:focus-visible,.tag:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n\n.inp{display:block;width:100%;min-width:0;height:26px;padding:0 8px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);font:inherit;outline:none}\n.inp:focus{border-color:var(--accent)}\ntextarea.inp{height:58px;padding:5px 8px;resize:none;line-height:1.4}\n.frow{display:flex;gap:6px;flex:none;min-width:0}\n.frow .qi{flex:1 1 0;width:auto}\n.frow .tsel{flex:none;width:72px;padding:0 2px}\n.sz-6x3 .frow .tsel{width:64px}\n\n.chips{display:flex;gap:5px;flex:none;overflow-x:auto;padding-bottom:2px;scrollbar-width:none}\n.chips::-webkit-scrollbar{display:none}\n.chip{flex:none;height:22px;padding:0 9px;border:1px solid var(--line);border-radius:11px;background:var(--panel-paper);color:var(--ink);font-size:11px;white-space:nowrap;line-height:1}\n.chip.on{background:var(--accent);color:var(--on-accent);border-color:var(--accent);font-weight:600}\n.chip.sm{height:20px;padding:0 8px}\n\n.lbox{flex:1;min-height:0;min-width:0;overflow-y:auto;display:flex;flex-direction:column;gap:5px;overscroll-behavior:contain}\n.lbox>*,.vlist>*,.fbody>*{flex:none}\n.row{display:flex;align-items:center;gap:7px;width:100%;min-width:0;text-align:left;padding:6px 7px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper);color:var(--ink)}\n.row.on{border-color:var(--accent);background:var(--soft)}\n.rtxt{flex:1;min-width:0;display:flex;flex-direction:column;gap:1px}\n.rname{font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.rsub{display:flex;gap:4px;min-width:0;font-size:10.5px;color:var(--muted);white-space:nowrap}\n.rsub .ad{flex:none;color:var(--ink);font-weight:600}\n.rsub .ad.no{color:var(--muted);font-weight:400}\n.rsub .ck{color:var(--accent)}\n.rsub .tp{min-width:0;overflow:hidden;text-overflow:ellipsis}\n.tile{flex:none;width:22px;height:22px;border-radius:6px;display:grid;place-items:center;font-size:11px;font-weight:700;border:1px solid transparent}\n.tile.sm{width:18px;height:18px;font-size:10px;border-radius:5px}\n.t-table{background:var(--accent);color:var(--on-accent)}\n.t-chart{background:var(--accent-alt);color:var(--on-accent)}\n.t-doc{background:var(--soft);color:var(--ink);border-color:var(--line)}\n.t-other{background:transparent;color:var(--muted);border-color:var(--line)}\n.empty{color:var(--muted);font-size:11.5px;padding:6px 2px;line-height:1.5}\n.empty.center{display:flex;align-items:center;justify-content:center;text-align:center}\n\n.dtop{display:flex;align-items:flex-start;gap:6px;flex:none}\n.dname{flex:1;min-width:0;padding-top:3px;font-weight:700;font-size:13px;line-height:1.3;overflow-wrap:anywhere;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}\n.tall .dname{display:block}\n.meta{display:flex;align-items:center;flex-wrap:wrap;gap:4px 6px;flex:none;font-size:11px;color:var(--muted)}\n.tag{border:0;background:var(--soft);color:var(--ink);border-radius:9px;padding:2px 8px;font-size:11px;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.vh{display:flex;align-items:center;justify-content:space-between;gap:6px;flex:none}\n.vt{font-weight:600;color:var(--muted)}\n.vlist{flex:1;min-height:0;min-width:0;overflow-y:auto;display:flex;flex-direction:column;gap:6px;overscroll-behavior:contain}\n.vcard{display:flex;flex-direction:column;gap:3px;min-width:0;padding:7px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper)}\n.wide .vcard{background:var(--paper)}\n.vcard.cur{border-color:var(--accent);background:var(--soft)}\n.vtop{display:flex;flex-wrap:wrap;align-items:center;gap:3px 6px}\n.vdate{font-weight:700;font-variant-numeric:tabular-nums}\n.vlab{color:var(--muted)}\n.badge{padding:1px 7px;border-radius:9px;background:var(--accent);color:var(--on-accent);font-size:10.5px;font-weight:600;white-space:nowrap}\n.vloc{color:var(--muted);font-size:11px;overflow-wrap:anywhere}\n.vnote{overflow-wrap:anywhere;white-space:pre-wrap}\n.vact{display:flex;flex-wrap:wrap;gap:5px;margin-top:2px}\n\n.fh{display:flex;align-items:center;gap:6px;flex:none}\n.ftt{min-width:0;font-weight:700;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.fbody{flex:1;min-height:0;overflow-y:auto;display:flex;flex-direction:column;gap:7px;padding-right:2px;overscroll-behavior:contain}\n.fld{display:flex;flex-direction:column;gap:2px;min-width:0}\n.fl{font-size:11px;color:var(--muted)}\n.sug{display:flex;flex-wrap:wrap;gap:4px}\n.ckl{display:flex;align-items:center;gap:6px}\n.ckl input{width:15px;height:15px;accent-color:var(--accent)}\n.err{flex:none;color:#B4533A;font-weight:600;font-size:11px;overflow-wrap:anywhere}\n.err:empty{display:none}\n.ffoot{display:flex;justify-content:flex-end;gap:6px;flex:none}\n";
const TYPES=[
  {id:'table',label:'数据表',ch:'表'},
  {id:'chart',label:'图表',ch:'图'},
  {id:'doc',label:'文稿',ch:'稿'},
  {id:'other',label:'其他',ch:'它'}
];
function typeOf(id){return TYPES.find(t=>t.id===id)||TYPES[3];}
function norm(s){
  const b=s&&typeof s==='object'?s:{};
  return Object.assign({},b,{materials:Array.isArray(b.materials)?b.materials:[]});
}
function patch(s,mid,fn){
  const n=norm(s);
  return Object.assign({},n,{materials:n.materials.map(x=>x.id===mid?fn(x):x)});
}
function sortedVers(m){
  return (m.versions||[]).map((v,i)=>({v,i}))
    .sort((a,b)=>a.v.date<b.v.date?1:a.v.date>b.v.date?-1:b.i-a.i).map(x=>x.v);
}
function curOf(m){return (m.versions||[]).find(v=>v.id===m.currentId)||null;}
function lastDate(m){return (m.versions||[]).reduce((a,v)=>(v.date>a?v.date:a),'');}
function sortedMats(list){
  return list.map((m,i)=>({m,i}))
    .sort((a,b)=>{const x=lastDate(a.m),y=lastDate(b.m);return x<y?1:x>y?-1:b.i-a.i;}).map(x=>x.m);
}
function topicsOf(mats){
  const out=[];
  mats.forEach(m=>{const t=(m.topic||'').trim();if(t&&out.indexOf(t)<0)out.push(t);});
  return out;
}
function clear(n){while(n.firstChild)n.removeChild(n.firstChild);}
function matches(m,q,topic,type){
  const tp=(m.topic||'').trim();
  if(topic==='__none'){if(tp)return false;}
  else if(topic&&tp!==topic)return false;
  if(type&&m.type!==type)return false;
  if(!q)return true;
  const hay=[m.name,tp,typeOf(m.type).label].concat((m.versions||[]).map(v=>[v.date,v.label,v.location,v.note].join(' '))).join(' ').toLowerCase();
  return q.toLowerCase().split(/\s+/).filter(Boolean).every(w=>hay.indexOf(w)>=0);
}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day,size}=ctx;
  const mats=norm(state).materials;
  const wide=size==='6x3'||size==='6x6';
  const tall=size==='3x6'||size==='6x6';
  if(typeof ui.q!=='string')ui.q='';
  if(typeof ui.topic!=='string')ui.topic='';
  if(typeof ui.type!=='string')ui.type='';
  if(!ui.sel||!mats.some(m=>m.id===ui.sel))ui.sel=null;
  if(ui.form&&ui.form.mid&&!mats.some(m=>m.id===ui.form.mid))ui.form=null;
  const selM=ui.sel?mats.find(m=>m.id===ui.sel):null;
  const topics=topicsOf(mats).sort((a,b)=>a.localeCompare(b,'zh'));
  const hasNone=mats.some(m=>!(m.topic||'').trim());
  if(ui.topic&&ui.topic!=='__none'&&topics.indexOf(ui.topic)<0)ui.topic='';
  if(ui.topic==='__none'&&!hasNone)ui.topic='';
  let listBox=null,cntEl=null,topicBox=null,typeBox=null;

  function btn(label,cls,fn,extra){
    return el('button',Object.assign({type:'button',class:'btn'+(cls?' '+cls:''),onclick:fn},extra||{}),label);
  }
  function chip(label,on,fn){
    return el('button',{type:'button',class:'chip'+(on?' on':''),onclick:fn},label);
  }
  function guard(p){
    return Promise.resolve(p).catch(e=>{
      const t='保存失败：'+(e&&e.message?e.message:'请重试');
      ui.saving=false;ui.msg=t;if(ui.form)ui.err=t;
      redraw();
    });
  }
  function openForm(f){ui.form=f;ui.err='';ui.msg='';ui.saving=false;redraw();}
  function openNew(){
    openForm({kind:'new',draft:{name:'',type:'table',topic:(ui.topic&&ui.topic!=='__none')?ui.topic:'',date:day(),label:'',location:'',note:'',adopt:true}});
  }
  function openEditMat(m){openForm({kind:'mat',mid:m.id,draft:{name:m.name,type:m.type,topic:m.topic||''}});}
  function openVNew(m){
    openForm({kind:'vnew',mid:m.id,draft:{date:day(),label:'',location:'',note:'',adopt:!curOf(m)}});
  }
  function openVEdit(m,v){
    openForm({kind:'vedit',mid:m.id,vid:v.id,draft:{date:v.date,label:v.label||'',location:v.location||'',note:v.note||'',adopt:m.currentId===v.id}});
  }
  function closeForm(){ui.form=null;ui.err='';redraw();}
  function pick(id){ui.sel=id;ui.form=null;ui.msg='';redraw();}
  function toList(){ui.sel=null;ui.form=null;ui.msg='';redraw();}
  function byTopic(t){ui.topic=t;ui.q='';ui.type='';ui.sel=null;ui.form=null;redraw();}


  function rowOf(m){
    const t=typeOf(m.type),c=curOf(m),tp=(m.topic||'').trim();
    const sub=el('span',{class:'rsub'});
    if(c){
      sub.append(el('span',{class:'ad'},el('b',{class:'ck'},'✓'),' '+c.date));
    }else{
      sub.append(el('span',{class:'ad no'},'未标采用'));
    }
    sub.append(el('span',{class:'tp'},'· '+(tp||'未设主题')));
    return el('button',{type:'button',class:'row'+(ui.sel===m.id?' on':''),title:m.name,onclick:()=>pick(m.id)},
      el('span',{class:'tile t-'+t.id,title:t.label},t.ch),
      el('span',{class:'rtxt'},el('span',{class:'rname'},m.name),sub));
  }

  function paintList(){
    if(!listBox)return;
    clear(listBox);
    const shown=sortedMats(mats).filter(m=>matches(m,ui.q.trim(),ui.topic,ui.type));
    if(cntEl)cntEl.textContent=mats.length?(shown.length===mats.length?String(mats.length):shown.length+'/'+mats.length):'';
    if(!mats.length){
      listBox.append(el('div',{class:'empty'},'还没有记录。点「+ 新增」登记第一份数据表、图表或文稿。'));
      return;
    }
    if(!shown.length){
      listBox.append(el('div',{class:'empty'},'没有符合条件的材料。'));
      listBox.append(btn('清除筛选','sm',()=>{ui.q='';ui.topic='';ui.type='';redraw();}));
      return;
    }
    shown.forEach(m=>listBox.append(rowOf(m)));
  }

  function paintChips(){
    if(!topicBox)return;
    const a=topicBox.scrollLeft,b=typeBox.scrollLeft;
    clear(topicBox);clear(typeBox);
    const setT=v=>()=>{ui.topic=v;paintChips();paintList();};
    topicBox.append(chip('全部主题',!ui.topic,setT('')));
    topics.forEach(t=>topicBox.append(chip(t,ui.topic===t,setT(t))));
    if(hasNone)topicBox.append(chip('未设主题',ui.topic==='__none',setT('__none')));
    const setY=v=>()=>{ui.type=v;paintChips();paintList();};
    typeBox.append(chip('全部类型',!ui.type,setY('')));
    TYPES.forEach(t=>typeBox.append(chip(t.label,ui.type===t.id,setY(t.id))));
    topicBox.scrollLeft=a;typeBox.scrollLeft=b;
  }

  function listPane(){
    cntEl=el('span',{class:'cnt'});
    const head=el('div',{class:'hd'},el('div',{class:'ttl'},'材料目录',cntEl),btn('+ 新增','pri',openNew));
    const qi=el('input',{class:'inp qi',type:'text',placeholder:tall?'搜名称、主题、位置、改动':'搜索材料',value:ui.q,
      oninput:e=>{ui.q=e.target.value;paintList();}});
    const pane=el('div',{class:'pane lp'});
    pane.append(head);
    if(tall){
      topicBox=el('div',{class:'chips'});
      typeBox=el('div',{class:'chips'});
      pane.append(qi,topicBox,typeBox);
    }else{
      const opts=[el('option',{value:''},'全部主题')];
      topics.forEach(t=>opts.push(el('option',{value:t},t)));
      if(hasNone)opts.push(el('option',{value:'__none'},'未设主题'));
      const sel=el('select',{class:'inp tsel','aria-label':'按研究主题查找',onchange:e=>{ui.topic=e.target.value;paintList();}},...opts);
      sel.value=ui.topic;
      pane.append(el('div',{class:'frow'},qi,sel));
    }
    listBox=el('div',{class:'lbox'});
    listBox.addEventListener('scroll',()=>{ui.ls=listBox.scrollTop;});
    pane.append(listBox);
    paintChips();
    paintList();
    return pane;
  }

  function vcard(m,v){
    const isCur=m.currentId===v.id;
    const card=el('div',{class:'vcard'+(isCur?' cur':'')});
    const top=el('div',{class:'vtop'},el('span',{class:'vdate'},v.date));
    if(v.label)top.append(el('span',{class:'vlab'},v.label));
    if(isCur)top.append(el('span',{class:'badge'},'✓ 当前采用'));
    card.append(top);
    if(v.location)card.append(el('div',{class:'vloc'},'位置 '+v.location));
    if(v.note)card.append(el('div',{class:'vnote'},'改动 '+v.note));
    const act=el('div',{class:'vact'});
    act.append(btn(isCur?'取消采用':'设为采用',isCur?'sm':'sm pri',()=>{
      ui.msg='';
      guard(update(s=>patch(s,m.id,x=>Object.assign({},x,{currentId:x.currentId===v.id?null:v.id}))));
    }));
    act.append(btn('编辑','sm',()=>openVEdit(m,v)));
    let armed=false;
    const del=btn('删除','sm',()=>{
      if(!armed){armed=true;del.textContent='确认删除';del.classList.add('warn');return;}
      ui.msg='';
      guard(update(s=>patch(s,m.id,x=>Object.assign({},x,{
        versions:(x.versions||[]).filter(y=>y.id!==v.id),
        currentId:x.currentId===v.id?null:x.currentId
      }))));
    },{onblur:()=>{armed=false;del.textContent='删除';del.classList.remove('warn');}});
    act.append(del);
    card.append(act);
    return card;
  }

  function detailPane(m){
    const t=typeOf(m.type),tp=(m.topic||'').trim(),vs=sortedVers(m);
    const pane=el('div',{class:'pane dp'});
    const top=el('div',{class:'dtop'});
    if(!wide)top.append(btn('←','ico',toList,{'aria-label':'返回列表',title:'返回列表'}));
    top.append(el('div',{class:'dname',title:m.name},m.name),btn('编辑','sm',()=>openEditMat(m)));
    const meta=el('div',{class:'meta'},el('span',{class:'tile sm t-'+t.id},t.ch),el('span',{},t.label));
    if(tp){
      meta.append(el('button',{type:'button',class:'tag',title:'查看这个主题下的全部材料',onclick:()=>byTopic(tp)},'# '+tp));
    }else{
      meta.append(el('span',{},'未设主题'));
    }
    const vh=el('div',{class:'vh'},el('span',{class:'vt'},'版本 '+vs.length),btn('+ 新版本','pri sm',()=>openVNew(m)));
    const vl=el('div',{class:'vlist'});
    if(!vs.length)vl.append(el('div',{class:'empty'},'这份材料还没有版本，点「+ 新版本」记录。'));
    vs.forEach(v=>vl.append(vcard(m,v)));
    pane.append(top,meta);
    if(ui.msg)pane.append(el('div',{class:'err',role:'alert'},'⚠ '+ui.msg));
    pane.append(vh,vl);
    return pane;
  }


  function formPane(){
    const f=ui.form,d=f.draft;
    const isMat=f.kind==='new'||f.kind==='mat',hasVer=f.kind!=='mat';
    const m=f.mid?mats.find(x=>x.id===f.mid):null;
    const titles={new:'新增材料',mat:'编辑材料',vnew:'新版本 · '+(m?m.name:''),vedit:'编辑版本 · '+(m?m.name:'')};
    const pane=el('div',{class:'pane fp'});
    pane.append(el('div',{class:'fh'},btn('←','ico',closeForm,{'aria-label':'返回',title:'返回'}),el('div',{class:'ftt'},titles[f.kind])));
    const body=el('div',{class:'fbody'});
    const fld=(label,node,req)=>el('label',{class:'fld'},el('span',{class:'fl'},label+(req?' *':'')),node);
    const inp=(k,ph,type)=>el('input',{class:'inp',type:type||'text',value:d[k]||'',placeholder:ph||'',
      oninput:e=>{d[k]=e.target.value;}});
    if(isMat){
      body.append(fld('材料名称',inp('name','例如：问卷原始数据'),true));
      const ts=el('select',{class:'inp',onchange:e=>{d.type=e.target.value;}},...TYPES.map(t=>el('option',{value:t.id},t.label)));
      ts.value=d.type||'table';
      body.append(fld('类型',ts));
      const ti=inp('topic','研究主题，如：睡眠与学习');
      body.append(fld('研究主题',ti));
      if(topics.length){
        const sg=el('div',{class:'sug'});
        topics.forEach(t=>sg.append(el('button',{type:'button',class:'chip sm',onclick:()=>{d.topic=t;ti.value=t;}},t)));
        body.append(sg);
      }
    }
    if(hasVer){
      body.append(fld('版本日期',inp('date','','date'),true));
      body.append(fld('版本号/名称（可选）',inp('label','如 v2、终稿')));
      body.append(fld('存放位置',inp('location','文件夹、网盘路径或链接')));
      const na=el('textarea',{class:'inp ta',placeholder:'相比上一版改了什么',value:d.note||'',
        oninput:e=>{d.note=e.target.value;}});
      body.append(fld('这次改了什么',na));
      const ck=el('input',{type:'checkbox',onchange:e=>{d.adopt=e.target.checked;}});
      ck.checked=!!d.adopt;
      body.append(el('label',{class:'ckl'},ck,el('span',{},'设为当前采用版本')));
    }
    if(f.kind==='mat'&&m){
      let armed=false;
      const dm=btn('删除这份材料','sm',()=>{
        if(!armed){
          armed=true;dm.classList.add('warn');
          dm.textContent='再点一次：删除材料及其 '+(m.versions||[]).length+' 个版本';
          return;
        }
        guard(commit(s=>{
          const n=norm(s);
          return Object.assign({},n,{materials:n.materials.filter(x=>x.id!==m.id)});
        },Object.assign({},ui,{form:null,sel:null,saving:false,err:'',msg:''})));
      });
